<script setup>
import { onMounted, ref } from 'vue'
const api = import.meta.env.VITE_API_BASE_URL || 'http://localhost:8080/api/v1'
const token = ref(localStorage.getItem('homestay_admin_token') || '')
const username = ref('admin'), password = ref('admin123'), error = ref(''), active = ref('概览')
const roomTypes = ref([]), rooms = ref([]), loading = ref(false), showForm = ref(false), editingId = ref(null), notice = ref('')
const form = ref({name:'',description:'',bedType:'1 张大床',area:32,maxGuests:2,price:688,coverImage:'/assets/room-warm.svg'})
async function login() { error.value=''; try { const r=await fetch(`${api}/auth/login`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({username:username.value,password:password.value})}); const d=await r.json(); if(!r.ok) throw Error(d.message||'登录失败'); token.value=d.data.token; localStorage.setItem('homestay_admin_token',token.value); await loadData() } catch(e) { error.value=e.message+'（请先注册账号或启动后端）' } }
async function loadData(){ loading.value=true; try { roomTypes.value=(await (await fetch(`${api}/admin/room-types`)).json()).data||[]; rooms.value=(await (await fetch(`${api}/admin/rooms`)).json()).data||[] } catch {} finally { loading.value=false } }
async function saveRoomType(){const method=editingId.value?'PUT':'POST';const url=editingId.value?`${api}/admin/room-types/${editingId.value}`:`${api}/admin/room-types`;const r=await fetch(url,{method,headers:{'Content-Type':'application/json',Authorization:`Bearer ${token.value}`},body:JSON.stringify(form.value)});const d=await r.json();if(!r.ok){notice.value=d.message||'保存失败';return}showForm.value=false;notice.value=d.message||'保存成功';await loadData()}
function startCreate(){editingId.value=null;form.value={name:'',description:'',bedType:'1 张大床',area:32,maxGuests:2,price:688,coverImage:'/assets/room-warm.svg'};showForm.value=true}
function startEdit(room){editingId.value=room.id;form.value={name:room.name,description:room.description||'',bedType:room.bedType||'',area:room.area,maxGuests:room.maxGuests,price:room.price,coverImage:room.coverImage||'/assets/room-warm.svg'};showForm.value=true}
function logout(){localStorage.removeItem('homestay_admin_token');token.value=''}
onMounted(()=>{if(token.value)loadData()})
</script>
<template>
<div v-if="!token" class="login-page"><div class="login-card"><div class="logo">栖</div><p class="kicker">QIYE OPERATIONS</p><h1>欢迎回来</h1><p class="sub">管理房源、订单与每一段入住时光。</p><form @submit.prevent="login"><label>账号<input v-model="username" autocomplete="username" required></label><label>密码<input v-model="password" type="password" autocomplete="current-password" required></label><button>进入管理台 <span>→</span></button><p v-if="error" class="error">{{error}}</p></form></div></div>
<div v-else class="admin-shell"><aside class="sidebar"><div class="brand"><span>栖</span><div><strong>栖野</strong><small>OPERATIONS</small></div></div><nav><button v-for="item in ['概览','房型管理','实体房间','订单管理','房客资料']" :key="item" :class="{active:active===item}" @click="active=item">{{item}}</button></nav><button class="logout" @click="logout">退出登录 ↗</button></aside><main class="content"><header><div><p class="kicker">SATURDAY, NOVEMBER 07, 2026</p><h1>{{active}}</h1></div><span class="avatar">{{username.slice(0,1).toUpperCase()}}</span></header><section v-if="active==='概览'"><div class="stats"><article><span>今日入住</span><strong>08</strong><small>较昨日 <b>+12%</b></small></article><article><span>当前在住</span><strong>24</strong><small>共 32 间房</small></article><article><span>本月收入</span><strong>¥86.4k</strong><small>入住率 <b>78%</b></small></article><article><span>待处理订单</span><strong>06</strong><small>需要及时跟进</small></article></div><div class="grid-two"><article class="panel"><p class="eyebrow">REVENUE OVERVIEW</p><h2>收入趋势</h2><div class="bars"><i v-for="h in [42,55,48,75,64,88,72]" :key="h" :style="{height:h+'%'}"></i></div><div class="days"><span v-for="d in ['周一','周二','周三','周四','周五','周六','周日']" :key="d">{{d}}</span></div></article><article class="panel"><p class="eyebrow">ROOM STATUS</p><h2>房态概览</h2><div class="room-status"><div>🟢 可售 <strong>18</strong></div><div>🟠 入住中 <strong>24</strong></div><div>⚪ 待清洁 <strong>03</strong></div><div>🔴 维修中 <strong>01</strong></div></div></article></div></section><section v-else class="panel list-panel"><div class="panel-head"><div><p class="eyebrow">PROPERTY MANAGEMENT</p><h2>{{active}}</h2></div><button class="primary" @click="active==='房型管理'&&startCreate()">+ 新增{{active}}</button></div><div v-if="loading" class="empty">正在加载…</div><div v-else-if="active==='房型管理' && roomTypes.length" class="table"><div v-for="room in roomTypes" :key="room.id" class="row"><div><strong>{{room.name}}</strong><small>{{room.description||room.bedType}}</small></div><span>¥{{room.price}} / 晚</span><em>已上架</em><button @click="startEdit(room)">编辑</button></div></div><div v-else class="empty"><strong>这里还没有数据</strong><small>连接后端后，你可以在这里管理{{active}}。</small></div></section><div v-if="showForm" class="modal-wrap"><form class="modal" @submit.prevent="saveRoomType"><h2>{{editingId?'编辑房型':'新增房型'}}</h2><label>房型名称<input v-model="form.name" required></label><label>描述<textarea v-model="form.description"></textarea></label><div class="form-grid"><label>床型<input v-model="form.bedType" required></label><label>价格<input v-model.number="form.price" type="number" min="1" required></label><label>面积<input v-model.number="form.area" type="number" min="1" required></label><label>人数<input v-model.number="form.maxGuests" type="number" min="1" required></label></div><div class="modal-actions"><button type="button" @click="showForm=false">取消</button><button class="primary" type="submit">保存房型</button></div></form></div><p v-if="notice" class="notice">{{notice}}</p></main></div>
</template>
